// === Tab: mySketch ===
var rows
var colours=[]
var n=5 // n>=3
var detail=100

setup=()=> {
  createCanvas(windowWidth, windowHeight)
  rows=0
  noiseSeed()
}

draw=()=> {
  for (let i=0; i<4; i++) {
    drawOneRow()
  }
}

drawOneRow=()=> {
  if (rows<height) {
    for (let cols=0; cols<width; cols++) {
      let x=cols/detail
      let y=rows/detail
      for (let i=0; i<n; i++) {
        let newx=sin(2*x)*cos(3*y+noise(x, y)*24)
        let newy=cos(3*x)*sin(2*y)
        x=newx
        y=newy
        colours[i]=abs(y)*256 // abs(x-y)*256 , abs(x+y)*256
      }
      stroke(colours[n-3], colours[n-2], colours[n-1])
      line(cols, rows, cols, rows+colours[n-1])
    }
    rows++
  }
}

mousePressed=()=>setup()
